  "PathExtrusionEditorTool": "<div id=\"dialog-path-extrusion\" class=\"floating-dialog\" style=\"top: 100px; left: 700px; width: 340px; display: none\">\n          <div class=\"dialog-header\">\n            <span class=\"dialog-title\"><i class=\"app-icon\" data-lucide=\"route\"></i> Path Extrusion</span>\n            <div class=\"dialog-actions\">\n              <button class=\"dialog-btn btn-help\" title=\"Help & Tool Guide\" aria-label=\"Help\"><i class=\"app-icon\" data-lucide=\"help-circle\"></i></button>\n            <button class=\"dialog-btn btn-min\" title=\"Minimize\"><i class=\"app-icon\" data-lucide=\"minus\"></i></button>\n              <button class=\"dialog-btn btn-close\" title=\"Close\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n            </div>\n          </div>\n          <div class=\"dialog-body path-extrusion-body\">\n            <!-- Active Path Extrusion Selector -->\n            <div class=\"path-extrusion-control-group\">\n              <label class=\"path-extrusion-label\" for=\"pathExtrusionSelect\">Active Path Extrusion</label>\n              <div class=\"path-extrusion-row\">\n                <select id=\"pathExtrusionSelect\" class=\"path-extrusion-select\"></select>\n                <button type=\"button\" class=\"btn btn-secondary btn-action-sm\" id=\"btnPathExtrusionNew\" title=\"Create new path extrusion\"><i class=\"app-icon\" data-lucide=\"plus\"></i></button>\n                <button type=\"button\" class=\"btn btn-secondary btn-action-sm btn-danger\" id=\"btnPathExtrusionDelete\" title=\"Delete path extrusion\"><i class=\"app-icon\" data-lucide=\"trash-2\"></i></button>\n              </div>\n            </div>\n\n            <!-- Open Path Extrusion Studio Button -->\n            <button type=\"button\" class=\"btn btn-primary btn-block mb-3\" id=\"btnOpenPathExtrusionStudio\" title=\"Open Interactive 2D Cross-Section Canvas & Presets Studio\" style=\"display:flex;align-items:center;justify-content:center;gap:6px;width:100%;padding:8px 12px;margin-bottom:12px;font-weight:600;\">\n              <i class=\"app-icon\" data-lucide=\"palette\"></i> Open Path Extrusion Studio\n            </button>\n\n            <!-- Help / Status info -->\n            <div class=\"path-extrusion-help-box\">\n              <div class=\"path-extrusion-help-title\"><i class=\"app-icon\" data-lucide=\"info\"></i> 3D Spline Sculpting</div>\n              <div class=\"path-extrusion-help-text\">\n                • <strong>Shift + Click</strong> on ground/mesh to place or append points.<br />\n                • Click any point sphere to attach 3D Gizmo and drag in space.\n              </div>\n            </div>\n\n            <!-- Action buttons -->\n            <div class=\"path-extrusion-actions\">\n              <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"btnPathExtrusionRemovePoint\" title=\"Delete selected waypoint\">\n                <i class=\"app-icon\" data-lucide=\"minus\"></i> Remove Point\n              </button>\n              <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"btnPathExtrusionClearPoints\" title=\"Clear all waypoints for this path extrusion\">\n                <i class=\"app-icon\" data-lucide=\"rotate-cw\"></i> Clear Points\n              </button>\n            </div>\n\n            <button type=\"button\" class=\"btn-path-extrusion-bake\" id=\"btnPathExtrusionBakeMesh\">\n              <i class=\"app-icon\" data-lucide=\"check\"></i> Bake to Scene Mesh\n            </button>\n          </div>\n        </div>",
